begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
insert into private.generation_worker_key values (true,encode(extensions.digest(repeat('a',64),'sha256'),'hex')) on conflict (singleton) do update set key_hash=excluded.key_hash;
select has_table('public','generation_jobs','Generation jobs exist');
select ok((select relrowsecurity from pg_class where oid='public.generation_jobs'::regclass),'Job RLS enabled');
select ok((select relrowsecurity from pg_class where oid='private.generation_worker_key'::regclass),'Worker key RLS enabled');
select ok(not has_table_privilege('authenticated','private.generation_worker_key','SELECT,INSERT,UPDATE,DELETE'),'Clients have no key privileges');
select ok(not has_table_privilege('authenticated','public.generation_jobs','INSERT,UPDATE,DELETE'),'Clients cannot mutate job records');
select ok(not has_function_privilege('anon','public.enqueue_generation(uuid)','EXECUTE'),'No anonymous enqueue');
select ok(not has_function_privilege('authenticated','private.require_generation_worker()','EXECUTE'),'Worker guard cannot be invoked directly');
select ok(not (select prosecdef from pg_proc where oid='public.finish_generation(uuid,jsonb,text)'::regprocedure),'Exposed completion wrapper is invoker');
select is((select proconfig[1] from pg_proc where oid='private.finish_generation(uuid,jsonb,text)'::regprocedure),'search_path=""','Elevated helper has empty search path');
select has_index('public','generation_jobs','generation_jobs_story_created_idx','Parent/history index exists');
select has_index('public','generation_jobs','generation_jobs_one_active_idx','One active job enforced by index');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"22222222-2222-4222-8222-222222222222"}',true);
set local role authenticated;
select set_config('test.bob_job',public.enqueue_generation('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1')::text,true);
reset role;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"11111111-1111-4111-8111-111111111111"}',true);
set local role authenticated;
select throws_ok($$select public.enqueue_generation('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1')$$,'42501','Story unavailable','Other owner cannot enqueue');
select throws_ok($$select public.enqueue_generation('00000000-0000-4000-8000-000000000000')$$,'42501','Story unavailable','Missing story uses same error');
select is_empty($$select * from public.generation_jobs$$,'Alice cannot see Bob job');
select set_config('test.job',public.enqueue_generation('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2')::text,true);
select is((select status from public.stories where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2'),'queued','Enqueue updates story');
select is(public.enqueue_generation('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2'),current_setting('test.job')::uuid,'Duplicate enqueue returns same job');
select is((select count(*) from public.generation_jobs),1::bigint,'Only owner job visible');
select throws_ok($$update public.generation_jobs set status='complete'$$,'42501',null,'Direct status update denied');
select throws_ok($$insert into public.generation_jobs(story_id) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2')$$,'42501',null,'Direct job insert denied');
select throws_ok($$select public.claim_generation(current_setting('test.job')::uuid,'mock')$$,'42501','Worker authorization required','Owner JWT alone cannot claim');
select throws_ok($$select public.finish_generation(current_setting('test.job')::uuid,null,'provider_timeout')$$,'42501','Worker authorization required','Owner JWT alone cannot finish');
select set_config('request.headers','{"x-generation-worker":"incorrect"}',true);
select throws_ok($$select public.claim_generation(current_setting('test.job')::uuid,'mock')$$,'42501','Worker authorization required','Forged worker header denied');
select set_config('request.headers',jsonb_build_object('x-generation-worker',repeat('a',64))::text,true);
select is(public.claim_generation(current_setting('test.bob_job')::uuid,'mock'),false,'Even worker proof cannot cross owner boundary');
select throws_ok($$select public.claim_generation(current_setting('test.job')::uuid,'unknown')$$,'22023','Invalid provider','Unknown provider rejected');
select is(public.claim_generation(current_setting('test.job')::uuid,'mock'),true,'Worker with owner JWT claims queued job');
select is(public.claim_generation(current_setting('test.job')::uuid,'mock'),false,'Duplicate claim cannot run twice');
select is((select status from public.stories where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2'),'generating','Claim updates story');
select throws_ok($$update public.stories set prompt='Changed during generation' where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2'$$,'23514','Story details are locked after generation starts','Input frozen during generation');
select throws_ok($$select public.finish_generation(current_setting('test.job')::uuid,'[]'::jsonb)$$,'22023','Expected five pages','Partial provider output rejected');
select is((select count(*) from public.story_pages where story_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2'),0::bigint,'Rejected output wrote no partial pages');
select is((select status from public.generation_jobs where id=current_setting('test.job')::uuid),'generating','Rejected transaction did not complete job');
select throws_ok($$select public.finish_generation(current_setting('test.job')::uuid,(select jsonb_agg(jsonb_build_object('page',1,'text','Duplicate page')) from generate_series(1,5)))$$,'22023','Invalid page','Repeated page numbers rejected');
select set_config('test.pages',(select jsonb_agg(jsonb_build_object('page',i,'text','Synthetic page '||i))::text from generate_series(1,5) i),true);
select is(public.finish_generation(current_setting('test.job')::uuid,current_setting('test.pages')::jsonb),true,'Valid output completes atomically');
select is((select count(*) from public.story_pages where story_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2'),5::bigint,'Exactly five pages saved');
select is((select status from public.stories where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2'),'complete','Story complete');
select is((select status from public.generation_jobs where id=current_setting('test.job')::uuid),'complete','Job complete');
select is(public.finish_generation(current_setting('test.job')::uuid,null,'provider_timeout'),false,'Late failure cannot overwrite success');
select is(public.enqueue_generation('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2'),null::uuid,'Completed story cannot regenerate');
select throws_ok($$update public.stories set title='Stale title' where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2'$$,'23514',null,'Completed input locked');
-- Recover a crashed worker and reject late writes from its previous attempt.
insert into public.stories(title,child_name,prompt) values ('Retry fixture','Nova','Map');
select set_config('test.retry_story',(select id::text from public.stories where title='Retry fixture'),true);
select set_config('test.old',public.enqueue_generation(current_setting('test.retry_story')::uuid)::text,true);
select is(public.claim_generation(current_setting('test.old')::uuid,'mock'),true,'First retry fixture claimed');
reset role;
update public.generation_jobs set lease_expires_at=clock_timestamp()-interval '1 second' where id=current_setting('test.old')::uuid;
set local role authenticated;
select is(public.finish_generation(current_setting('test.old')::uuid,current_setting('test.pages')::jsonb),false,'Expired worker cannot publish');
select set_config('test.new',public.enqueue_generation(current_setting('test.retry_story')::uuid)::text,true);
select isnt(current_setting('test.new'),current_setting('test.old'),'Expired run replaced with a new attempt');
select is((select error_code from public.generation_jobs where id=current_setting('test.old')::uuid),'interrupted','Expired run records safe failure');
select is(public.claim_generation(current_setting('test.new')::uuid,'gemini'),true,'Second attempt claimed');
select throws_ok($$select public.finish_generation(current_setting('test.new')::uuid,null,'raw API secret failure')$$,'22023','Invalid failure','Arbitrary provider errors cannot be stored');
select is(public.finish_generation(current_setting('test.new')::uuid,null,'provider_timeout'),true,'Timeout stored as safe failure');
select is((select status from public.stories where id=current_setting('test.retry_story')::uuid),'failed','Failure updates story');
select lives_ok($$update public.stories set prompt='A revised idea' where id=current_setting('test.retry_story')::uuid$$,'Failed input may be revised');
select set_config('test.third',public.enqueue_generation(current_setting('test.retry_story')::uuid)::text,true);
select is(public.claim_generation(current_setting('test.third')::uuid,'mock'),true,'Third attempt allowed');
select is(public.finish_generation(current_setting('test.old')::uuid,current_setting('test.pages')::jsonb),false,'Old result cannot corrupt new run');
select is(public.finish_generation(current_setting('test.third')::uuid,null,'invalid_output'),true,'Third failure recorded');
select is(public.enqueue_generation(current_setting('test.retry_story')::uuid),null::uuid,'Attempt cap stops fourth attempt');
select lives_ok($$delete from public.stories where id=current_setting('test.retry_story')::uuid$$,'Owner may delete failed story');
select is(public.finish_generation(current_setting('test.third')::uuid,current_setting('test.pages')::jsonb),false,'Deleted job cannot publish');
insert into public.stories(title,child_name,prompt) values ('Delete active fixture','Nova','Map');
select set_config('test.delete_story',(select id::text from public.stories where title='Delete active fixture'),true);
select set_config('test.delete_job',public.enqueue_generation(current_setting('test.delete_story')::uuid)::text,true);
select is(public.claim_generation(current_setting('test.delete_job')::uuid,'mock'),true,'Deletion fixture is actively generating');
select lives_ok($$delete from public.stories where id=current_setting('test.delete_story')::uuid$$,'Owner deletion cancels active persistence');
select is(public.finish_generation(current_setting('test.delete_job')::uuid,current_setting('test.pages')::jsonb),false,'An active deleted story cannot be resurrected');
reset role;
select set_config('request.jwt.claims','{"role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$select public.enqueue_generation('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2')$$,'42501',null,'Missing uid cannot enqueue');
select throws_ok($$select public.claim_generation(current_setting('test.bob_job')::uuid,'mock')$$,'42501',null,'Worker secret alone without user cannot claim');
select is_empty($$select * from public.generation_jobs$$,'Missing uid cannot read jobs');
reset role;
set local role anon;
select throws_ok($$select * from public.generation_jobs$$,'42501',null,'Anonymous cannot read jobs');
select * from finish();
rollback;
